import numpy as np
from collections import defaultdict

def simplified_single_ender_random_logic(called_samples, pair_samples, min_support=4, max_samples=40, min_frac_samples=0.5):
    if len(called_samples) > max_samples:
        called_samples = np.random.choice(called_samples, max_samples, replace=False).tolist()
    sample_support = defaultdict(int)
    for (sample_id, support_count) in pair_samples:
        if sample_id in called_samples:
            sample_support[sample_id] += support_count
    n_supported_samples = sum((support_count > min_support for support_count in sample_support.values()))
    is_supported = n_supported_samples >= min_frac_samples * len(called_samples)
    return (called_samples, sample_support, n_supported_samples, is_supported)

