from scipy.stats import gaussian_kde

def compute_kde_values(data, x_min=0, x_max=1, n_points=1000):
    data = np.array(data)
    if len(data.shape) == 1:
        data = data.reshape((1, -1))
    results = {}
    space = np.linspace(x_min, x_max, n_points)
    for (i, row) in enumerate(data):
        kde = gaussian_kde(row)
        density = kde(space)
        results[i] = (space, density)
    return results

