import numpy as np
import torch

def mock_model_predict(X):
    return X.mean(dim=(1, 2))

def shuffle_region(X, start, end, n=1, random_state=None):
    X = X.clone()
    rng = np.random.RandomState(random_state)
    perturbed = []
    for _ in range(n):
        X_perturb = X.clone()
        for i in range(X.shape[0]):
            for c in range(X.shape[1]):
                region = X_perturb[i, c, start:end].numpy()
                rng.shuffle(region)
                X_perturb[i, c, start:end] = torch.tensor(region)
        perturbed.append(X_perturb)
