            X[b, idx, l] = 1
    return X

def simulate_screen_random(shape, n_best=1, batch_size=32, random_state=None, verbose=False):
    pq = []
    iteration = 0
    while len(pq) < n_best:
        X_batch = random_one_hot((batch_size, *shape), random_state=random_state)
        y_hat = torch.rand(batch_size)
        loss_vals = y_hat.numpy()
        for i in range(batch_size):
            l = -loss_vals[i]
            entry = [l, X_batch[i]]
            if len(pq) < n_best:
                heapq.heappush(pq, entry)
            elif l > pq[0][0]:
                heapq.heappushpop(pq, entry)
            if verbose:
                print(f'Iteration {iteration}, adding element with score {l:.4f}')
        iteration += 1
        if random_state is not None:
            random_state += 1
    Xs = [heapq.heappop(pq)[1] for _ in range(n_best)]
    X_out = torch.stack(list(reversed(Xs)))
    return X_out

