def fast_shuffle_simulated(n_shuffles, n_chars, idxs, sequence_length):
    shuffled_sequences = torch.zeros((n_shuffles, n_chars, sequence_length))
    for i in range(n_shuffles):
        next_idxs = {}
        for char in range(n_chars):
            n = idxs.count(char)
            if n > 1:
                perm = np.random.permutation(n - 1)
                perm = np.append(perm, n - 1)
            else:
                perm = np.array([0])
            next_idxs[char] = perm
        counters = {char: 0 for char in range(n_chars)}
        idx = 0
        shuffled_sequences[i, idxs[idx], 0] = 1
        for j in range(1, sequence_length):
            char = idxs[idx]
            count = counters[char]
            next_idx = next_idxs[char][count % len(next_idxs[char])]
            counters[char] += 1
            shuffled_sequences[i, next_idx, j] = 1
    return shuffled_sequences

