def chunk(data, size, overlap):
    chunks = []
    for tensor in data:
        for start in range(0, tensor.size(1) - size + 1, size - overlap):
            chunks.append(tensor[:, start:start + size])
    return chunks

def unchunk(chunks, lengths, overlap):
    max_length = max(lengths)
    result = [torch.zeros((chunks[0].size(0), max_length)) for _ in lengths]
    for (i, chunk) in enumerate(chunks):
        result[i % len(result)][:, :chunk.size(1)] = chunk
    return result

